const breakpoints = [
  "--breakpoint-xs",
  "--breakpoint-sm",
  "--breakpoint-md",
  "--breakpoint-lg",
  "--breakpoint-xl",
  "--breakpoint-xxl",
  "--breakpoint-xxxl",
  "--breakpoint-4xl"
];

function computeOwlItems(size, value) {
  let buffer = size.split("-");
  let current_size = buffer[buffer.length - 1];
  if (current_size == "xs") return 2;
  else if (current_size == "sm") return 2;
  else if (current_size == "md") return 3;
  else if (current_size == "lg") return 4;
  else if (current_size == "xl") return 5;
  else if (current_size == "xxl") return 6;
  else if (current_size == "xxxl") return 7;
  else if (current_size == "4xl") return 9;
  return 2;
}

function computeOwlResponsiveConfig() {
  let responsive = { 0: { items: 2 } };
  for (let i = breakpoints.length - 1; i >= 0; i--) {
    let breakpoint = breakpoints[i];
    let value = parseInt(getCssVarValue(breakpoint));
    responsive[value] = { items: computeOwlItems(breakpoint, value) };
  }
  return responsive;
}

function getCssVarValue(variable) {
  return getComputedStyle(document.documentElement).getPropertyValue(variable);
}

function getOwlCarousel() {
  return $(".owl-carousel");
}

function initOwlCarousel() {
  let owl_carousel = getOwlCarousel();
  owl_carousel.owlCarousel({
    margin: 0,
    loop: true,
    nav: false,
    dots: false,
    autoplay: true,
    responsive: computeOwlResponsiveConfig()
  });
}

$(document).ready(function() {
  let section_menu = $(".section-menu");
  let nav_open = $(".action-nav a.open");
  let nav_close = $(".action-nav a.close");
  let body = $("body");

  nav_open.click(() => {
    body.css("overflow", "hidden");
    section_menu.addClass("fullscreen");
  });

  nav_close.click(() => {
    body.css("overflow", "inherit");
    section_menu.removeClass("fullscreen");
  });

  initOwlCarousel();
});

$(function () {
  if ($("body").hasClass("homePage")) {
    let $slides = $(".supersliderHome");

    Hammer($slides[0]).on("swipeleft", function (e) {
      $slides.data("superslides").animate("next");
    });

    Hammer($slides[0]).on("swiperight", function (e) {
      $slides.data("superslides").animate("prev");
    });

    $slides.superslides({
      play: 5000,
      hashchange: true,
      pagination: false,
    });
  }
});

"use strict";

$(function () {
  if ($("body").hasClass("resultPage")) {
    let mixer = mixitup(".listCardsResult");

    function getText(id) {
      return $(id)
        .text()
        .toLowerCase()
        .replace(/ /g, "");
    }

    function getFormData() {
      let cat = getText("#idCategory option:selected");
      let team = getText("#idTeam option:selected");
      let journey = getText("#idJourney option:selected");

      return { cat, team, journey };
    }

    $(".formFilters").submit(function (event) {
      event.preventDefault();
      let { cat, team, journey } = getFormData();

      let filter = "";

      if (cat != "todos") filter = filter + "." + cat;
      if (team != "todos") filter = filter + "." + team;
      if (journey != "todos") filter = filter + "." + journey;
      if (filter == "") filter = "*";

      mixer.filter(filter);
    });
  }
});

$(function() {
  if ($("body").hasClass("calendarPage")) {
    let container_id = ".listCardsResult";
    let container = $(container_id);

    let mixer = mixitup(container_id);

    function getText(id) {
      return $(id)
        .text()
        .toLowerCase()
        .replace(/ /g, "");
    }

    function getFormData() {
      let cat = getText("#idCategory option:selected");
      let team = getText("#idTeam option:selected");
      let journey = getText("#idJourney option:selected");

      return { cat, team, journey };
    }

    function filter() {
      let { cat, team, journey } = getFormData();

      let filter = "";

      if (cat != "todos") filter = filter + "." + cat;
      if (team != "todos") filter = filter + "." + team;
      if (journey != "todos") filter = filter + "." + journey;
      if (filter == "") filter = "*";

      mixer.filter(filter).then(() => container.show());
    }

    $(".formFilters").submit(function(event) {
      event.preventDefault();
      filter();
    });

    filter();
  }
});

$(function () {
  if ($("body").hasClass("contactPage")) {
    let map;
    let Lat = parseFloat($(".mapContact").attr("data-lat"));
    let Lon = parseFloat($(".mapContact").attr("data-lon"));
    initMap();
    function initMap() {
      map = new google.maps.Map(document.getElementById("map"), {
        center: { lat: Lat, lng: Lon },
        zoom: 12,
      });

      let marker = new google.maps.Marker({
        position: { lat: Lat, lng: Lon },
        map: map,
      });
    }
  }
});

$(function() {
  if ($("body").hasClass("cheerleaderPage")) {

    let data = document.querySelectorAll(".assets");
    let timers = [];

    function toggleSlider(assets) {
      let image_hidden_count = assets.querySelectorAll(".asset.hidden").length;

      if (image_hidden_count == 0) return;

      let image_hidden_last = assets.querySelector(".asset.hidden:not(.last)");

      if (!image_hidden_last && image_hidden_count > 2) return;

      if (image_hidden_count == 1)
        image_hidden_last = assets.querySelector(".asset.hidden");

      let image_last = assets.querySelector(".asset.hidden.last");
      let image_showing = assets.querySelector(".asset:not(.hidden)");

      if (image_last) image_last.classList.remove("last");

      image_showing.classList.add("hidden", "last");
      image_hidden_last.classList.remove("hidden");
    }

    function stopSlider(index) {
      if (timers[index]) {
        clearTimeout(timers[index]);
      }
    }

    function initSlider() {
      for (let i = 0, length = data.length; i < length; i++) {
        const assets = data[i];
        $(assets.parentElement).click(onTeamClick);
        registerSlider(assets, i);
      }
    }

    function registerSlider(assets, index) {
      timers[index] = setTimeout(function() {
        toggleSlider(assets);
      }, randomNumber(5000, 12000));
    }

    function onTeamClick(event) {
      let current_target = event.currentTarget;
      let index = parseInt(current_target.dataset.index);
      let assets = parseAssets(teams[index].assets);
      Fresco.show(assets, {
        youtube: {
          autohide: 1,
          autoplay: 1,
          controls: 1,
          enablejsapi: 1,
          hd: 1,
          iv_load_policy: 3,
          loop: 0,
          modestbranding: 1,
          showinfo: 0,
          rel: 0,
          vq: 'hd1080'
        },
        onShow() {
          document.querySelector("html").style.overflow = "hidden";
        },
        afterHide() {
          document.querySelector("html").style.overflow = "initial";
        }
      });
    }

    function parseAssets(assets) {
      return assets.map(asset => {
        return { url: asset.source, caption: asset.title };
      });
    }

    initSlider();
  }
});
